// 片中用到的字体（只含用到的字，woff2），由 tools/make_fonts.py 生成，不要手改
// 内嵌进网页，换一台电脑打开也是同样的字形；字体许可：Noto Serif CJK / DejaVu 均可自由再分发
const FONT_FACES=[
["Noto Serif CJK SC",400,""],
["Noto Serif CJK SC",500,""],
["Noto Serif CJK SC",600,""],
["Noto Serif CJK SC",700,""],
["DejaVu Sans Mono",400,""],
];
const FONTS_READY=Promise.all(FONT_FACES.map(([fam,w,b64])=>{const s=atob(b64);const u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);const f=new FontFace(fam,u.buffer,{weight:String(w)});document.fonts.add(f);return f.load();}));
